316    /**
317     * 打开一场。
318     * @param id 会话号。
319     * @returns 会话对象。同一场永远交回同一个对象。
320     * @throws 没有这场时抛错。
321     */
322    open(id: string): Session {
323      //M 先查内存里已打开的会话对象，直接复用以保持运行开关和未入队消息一致。
324      const opened = this.openedSessions.get(id);
325      if (opened !== undefined) return opened;
326  
327      //M 库里的两块读出来，拼回一份记录。
328      const sql = 'SELECT meta, messages FROM sessions WHERE id = ?';
329      const query = this.ctx.resources.db.query(sql);
330      const stored = query.get(id) as { meta: string; messages: string } | null;
331  
332      //G 库里没有 → 抛错。
333      if (stored === null) {
334        throw new Error(`没有这场会话：${id}`);
335      }
336  
337      //M 解析磁盘元信息与对话历史重建会话实例，并放入 openedSessions 供同一场对话复用。
338      const meta = JSON.parse(stored.meta) as SessionMeta;
339      const messages = JSON.parse(stored.messages) as piAi.Message[];
340      const session = new Session({ ...meta, messages }, this.ctx);
341      this.openedSessions.set(id, session);
342      return session;
343    }
344  
```

### 解释
- 输入会话号；输出 Session，同一场永远交回同一个对象。
- 三步见下面三个子块。

