496    /**
497     * 推这场对话往下走，走到做完、停下或者出错为止。自己不往外抛。
498     * 谁都可以调：插件把话交给它以后、重启后接着跑。已经在转就直接返回，刚说的话下一步会带上。
499     * 副作用：发事件、调模型、执行工具、写库。
500     */
501    async run(): Promise<void> {
502      //G 已经在转 → return。
503      if (this.aborter !== undefined) return;
504  
505      //M 备好这一轮的取消开关，状态改成 running，跑循环；不管怎么结束都把开关收掉。
506      const aborter = new AbortController();
507      this.aborter = aborter;
508      this.change('running', '');
509      try {
510        await this.loop(aborter.signal);
511      } catch (error) {
512        //G 被喊停时请求是被掐断的，状态已经是 stopped；还是 running 才算出错。
513        if (this.row.state === 'running') {
514          const reason = textModule.getMessage(error);
515          this.change('failed', `出错了：${reason}`);
516        }
517      } finally {
518        this.aborter = undefined;
519      }
520  
521      //G 收尾的那一下又有人说话 → 再转一轮。喊停后慢工具还在收尾时来的话也在这里转，不然要等下一句话才处理。
522      if (this.inbox.length > 0) {
523        void this.run();
524      }
525    }
526  
```

