527    /**
528     * 循环本身：一步 = 调一次模型，加上执行它要的工具。不数步数，一直走到下面三种情况之一：
529     * 模型不再要工具（做完了）；有人喊停（stop()）；某个关口上有插件写了 stop。
530     * @param signal 这一轮的取消信号。
531     */
532    private async loop(signal: AbortSignal): Promise<void> {
533      //M step 只用来记这是第几步（给跟踪看），不拿它限制会话。
534      for (let step = 1; ; step += 1) {
535        //G 被喊停了 → 不往下走。
536        if (this.row.state !== 'running') return;
537  
538        //M 用户说了、还没接进对话的话，这时候接进去。
539        for (const waiting of this.inbox.splice(0)) {
540          this.append(waiting);
541        }
542  
543        //M 关口一，调模型之前：备好这一步的请求，交给插件挨个改（session/request）。
544        const request: ChatRequest = {
545          session: this,
546          model: this.row.model,
547          thinking: this.row.thinking,
548          system: [],
549          tools: this.ctx.tools.list(this.row.kind),
550          messages: [...this.row.messages],
551          signal,
552        };
553        await this.ctx.serial('session/request', request);
554  
555        //G 有插件喊停 → 不调模型，这一轮停在这里，理由写进 reply。
556        if (request.stop !== undefined) {
557          this.stop(request.stop);
558          return;
559        }
560  
561        //T 跟踪：调模型；插件已经给了回答（假模型）就写明没有调。
562        const vars = {
563          会话: this.id,
564          第几步: step,
565          模型: request.model,
566          对话几条: request.messages.length,
567        };
568        let doing = '调模型';
569        if (request.answer !== undefined) {
570          doing = '插件已经给了回答，不调模型';
571        }
572        this.ctx.emit('trace', 'Session.loop', doing, 'ctx.sessions.chat(request)', vars);
573  
574        //M 调模型（Sessions.chat，就在本文件上面）。插件已经给了回答（假模型）就不发请求。
575        let answer = request.answer;
576        if (answer === undefined) {
577          answer = await this.ctx.sessions.chat(request);
578        }
579  
580        //G 等模型的时候被喊停了 → 这次回答不要了。
581        if (this.row.state !== 'running') return;
582  
583        //M 关口二，模型回来之后：回答接进对话之前，带着回答交给插件挨个看（session/after-model）。
584        const answered: AnsweredRequest = { ...request, answer };
585        await this.ctx.serial('session/after-model', answered);
586  
587        //G 有插件喊停 → 这次回答不要了（里面要的工具也不执行），这一轮停在这里。
588        if (answered.stop !== undefined) {
589          this.stop(answered.stop);
590          return;
591        }
592  
593        //M 插件可能改了、换了回答，以最后这一份为准，接进对话。
594        answer = answered.answer;
595        this.append(answer);
596  
597        //M 从回答里挑出工具调用。
598        const calls = answer.content.filter((block): block is piAi.ToolCall => {
599          return block.type === 'toolCall';
600        });
601  
602        //M 模型没要工具 → 这一轮做完了，它说的就是回给用户的话。
603        if (calls.length === 0) {
604          const reply = piAi.contentText(answer.content);
605          this.change('done', reply);
606          return;
607        }
608  
609        //M 模型要了工具 → 一个个执行（关口三 session/before-tool 在 Tools.execute 里），结果接进对话，回到开头走下一步。
610        for (const call of calls) {
611          const executed = await this.ctx.tools.execute(call, this, signal);
612  
613          //M 关口四，工具执行之后：结果接进对话之前，交给插件挨个看（session/after-tool）。
614          const done: ToolDone = { session: this, call, outcome: executed };
615          await this.ctx.serial('session/after-tool', done);
616  
617          //M 插件可能改了结果，以改过的为准。
618          const outcome = done.outcome;
619  
620          //M 结果写成一条 toolResult：先是文字，后面跟着图片（有的话）。
621          const textBlock: piAi.TextContent = { type: 'text', text: outcome.text };
622          const images = outcome.images ?? [];
623          const result: piAi.Message = {
624            role: 'toolResult',
625            toolCallId: call.id,
626            toolName: call.name,
627            content: [textBlock, ...images],
628            isError: outcome.isError,
629            timestamp: Date.now(),
630          };
631          //M 把打包好的工具结果追加到对话历史并落库广播，供下一步继续喂给模型。
632          this.append(result);
633  
634          //G 有插件喊停 → 这一轮停在这里。结果已经接进对话（要和工具调用配对）；
635          //G   这一批后面的工具，Tools.execute 看到停了就不执行，只交回“未执行”接进对话。
636          if (done.stop !== undefined) {
637            this.stop(done.stop);
638          }
639        }
640      }
641    }
